function formatNoticeDate(value){const date=new Date(`${value}T12:00:00`);return {day:String(date.getDate()),month:new Intl.DateTimeFormat('es-ES',{month:'short'}).format(date).replace('.','').toUpperCase(),label:new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'long',year:'numeric'}).format(date)};}
function renderCalendar(){const grid=document.querySelector('#calendarGrid'),label=document.querySelector('#calendarMonthLabel'),events=document.querySelector('#calendarEvents');if(!grid||!label||!events)return;const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),monthName=new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(calendarMonth);label.textContent=monthName.charAt(0).toUpperCase()+monthName.slice(1);const firstDay=(new Date(year,month,1).getDay()+6)%7,daysInMonth=new Date(year,month+1,0).getDate();const cells=[];for(let i=0;i<firstDay;i++)cells.push('<span class="calendar-day is-empty"></span>');for(let day=1;day<=daysInMonth;day++){const iso=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,dayNotices=notices.filter(item=>item.eventDate===iso);cells.push(`<span class="calendar-day${dayNotices.length?' has-event':''}${iso===new Date().toISOString().slice(0,10)?' is-today':''}><b>${day}</b>${dayNotices.length?`<small>${dayNotices.length} aviso${dayNotices.length===1?'':'s'}</small>`:''}</span>`);}grid.innerHTML=cells.join('');const monthEvents=notices.filter(item=>item.eventDate&&item.eventDate.slice(0,7)===`${year}-${String(month+1).padStart(2,'0')}`);events.innerHTML=monthEvents.length?`<p class="eyebrow">AVISOS DE ESTE MES</p>${monthEvents.map(item=>`<div class="calendar-event"><strong>${formatNoticeDate(item.eventDate).label}</strong><span>${escapeHtml(item.title)}</span></div>`).join('')}`:'<p class="documents-empty">No hay avisos con fecha en este mes.</p>';}
function renderCalendar(){
  const grid=document.querySelector('#calendarGrid'),label=document.querySelector('#calendarMonthLabel'),events=document.querySelector('#calendarEvents');
  if(!grid||!label||!events)return;
  const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth();
  const monthName=new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(calendarMonth);
  label.textContent=monthName.charAt(0).toUpperCase()+monthName.slice(1);
  const firstDay=(new Date(year,month,1).getDay()+6)%7;
  const daysInMonth=new Date(year,month+1,0).getDate();
  const todayIso=new Date().toISOString().slice(0,10);
  const cells=[];
  for(let i=0;i<firstDay;i++)cells.push('<div class="calendar-day is-empty" aria-hidden="true"></div>');
  for(let day=1;day<=daysInMonth;day++){
    const iso=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
    const dayNotices=notices.filter(item=>item.eventDate===iso);
    const classes=['calendar-day'];
    if(dayNotices.length)classes.push('has-event');
    if(iso===todayIso)classes.push('is-today');
    cells.push(`<div class="${classes.join(' ')}" aria-label="${day} de ${monthName}"><span class="calendar-number">${day}</span>${dayNotices.length?`<small>${dayNotices.length} aviso${dayNotices.length===1?'':'s'}</small>`:''}</div>`);
  }
  grid.innerHTML=cells.join('');
  const monthEvents=notices.filter(item=>item.eventDate&&item.eventDate.slice(0,7)===`${year}-${String(month+1).padStart(2,'0')}`);
  events.innerHTML=monthEvents.length?`<p class="eyebrow">AVISOS DE ESTE MES</p>${monthEvents.map(item=>`<div class="calendar-event"><strong>${formatNoticeDate(item.eventDate).label}</strong><span>${escapeHtml(item.title)}</span></div>`).join('')}`:'<p class="documents-empty">No hay avisos con fecha en este mes.</p>';
}
function renderNotices(){ noticeList.innerHTML = notices.length ? notices.map((n,index) => `<article class="notice-card"><div class="notice-date"><b>${escapeHtml(n.date)}</b>${escapeHtml(n.month)}</div><div class="notice-copy"><h3>${escapeHtml(n.title)}</h3><p>${escapeHtml(n.message)}</p></div><span class="notice-tag">${escapeHtml(n.tag)}</span>${currentRole==='admin'?`<button class="notice-remove" type="button" data-notice-id="${escapeHtml(n.id||'')}" data-notice-index="${index}" aria-label="Eliminar aviso">Eliminar</button>`:''}</article>`).join('') : '<p class="documents-empty">Todavía no hay avisos publicados.</p>'; noticeList.querySelectorAll('[data-notice-index]').forEach(button=>button.onclick=async()=>{const index=Number(button.dataset.noticeIndex);if(!Number.isInteger(index)||!notices[index])return;if(!window.confirm(`¿Quieres eliminar el aviso «${notices[index].title}»?`))return;if(notices[index].id&&supabaseClient&&supabaseSession){await deleteRemoteNotice(notices[index].id);return;}notices.splice(index,1);renderNotices();renderCalendar();showToast('Aviso eliminado.');}); }
const incidentStatusLabels={pending:'Pendiente',reviewed:'Tramitado',resolved:'Solucionado',cancelled:'Eliminado'};
function incidentCard(i,index=0){const status=incidentStatusLabels[i.status]||i.status||'Pendiente';const id=escapeHtml(i.id||'');const isHistory=['resolved','cancelled'].includes(String(i.status||'').toLowerCase());const isIncident=String(i.type||'Incidencia').toLowerCase()!=='sugerencia';const failed=i.email_status==='failed';const alreadySent=Boolean(i.sent_at)||i.email_status==='sent';let incidentAttachments=i.attachments||[];if(typeof incidentAttachments==='string'){try{incidentAttachments=JSON.parse(incidentAttachments);}catch{incidentAttachments=[];}}const photoCount=Array.isArray(incidentAttachments)?incidentAttachments.length:0;const photoButton=isIncident&&photoCount?`<button type="button" class="incident-photo-btn" data-incident-photos="${id}">Ver fotos (${photoCount})</button>`:'';const actions=currentRole==='admin'&&!isHistory&&i.id?`<div class="incident-actions">${isIncident&&!alreadySent?`<button type="button" data-incident-email="${id}">${failed?'Reenviar correo':'Enviar correo'}</button>`:''}${i.status!=='reviewed'?`<button type="button" data-incident-status="reviewed" data-incident-id="${id}">Tramitado</button>`:''}<button type="button" data-incident-status="resolved" data-incident-id="${id}">Solucionado</button><button type="button" data-incident-delete="${id}">Eliminar</button></div>`:'';const resident=approvedResidents.find(item=>String(item.anonymous_user_id||'')===String(i.created_by||''));const reporter=resident?.full_name||i.reporter_name||i.neighbor_name||i.full_name||i.created_by_name||i.requester_name||i.user_name||(currentRole==='admin'&&supabaseSession?.user?.id&&String(i.created_by)===String(supabaseSession.user.id)?'Administrador de la aplicación':'');const reporterPhone=resident?.phone||i.reporter_phone||i.neighbor_phone||i.phone||'';const reporterFloor=resident?.floor||i.reporter_floor||i.neighbor_floor||i.floor||'';const reporterInfo=currentRole==='admin'&&reporter?'<small class="incident-reporter">Comunica: '+escapeHtml(reporter)+(reporterPhone?' · Teléfono: '+escapeHtml(reporterPhone):'')+(reporterFloor?' · Piso: '+escapeHtml(reporterFloor):'')+'</small>':'';const emailInfo=alreadySent?' · Correo enviado':failed?' · Pendiente de envío':'';return `<article class="incident-card"><span class="incident-icon">⌁</span><div><h3>${index+1}. ${escapeHtml(i.title)}</h3><p>${escapeHtml(i.message||i.text||'')}${i.location?` · ${escapeHtml(i.location)}`:''}</p><small>${escapeHtml(i.type||'Incidencia')} · ${i.created_at?new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(i.created_at)):escapeHtml(i.text||'')}${emailInfo}</small>${reporterInfo}${photoButton}${failed&&currentRole==='admin'?`<small class="incident-email-error">Error de envío: ${escapeHtml(i.email_error||'No se pudo enviar el correo.')}</small>`:''}${actions}</div><span class="incident-status">${escapeHtml(status)}</span></article>`;}
async function openIncidentPhotos(incidentId){const item=remoteIncidents.find(entry=>String(entry.id)===String(incidentId));const attachments=Array.isArray(item?.attachments)?item.attachments:[];if(!attachments.length){showToast('Esta incidencia no tiene fotos adjuntas.');return;}const links=[];for(const photo of attachments){const path=String(photo?.path||'').trim();if(!path)continue;const {data,error}=await supabaseClient.storage.from('incident-photos').createSignedUrl(path,300);if(!error&&data?.signedUrl)links.push(`<p><a href="${data.signedUrl}" target="_blank" rel="noopener">${escapeHtml(photo?.name||'Abrir foto')}</a></p>`);}const panel=document.querySelector('#notificationsPanel');if(panel){panel.hidden=false;panel.innerHTML='<strong>Fotos de la incidencia</strong>'+(links.length?links.join(''):'<p>No se pudieron abrir las fotos.</p>');}else if(links.length)window.open(links[0].match(/href="([^"]+)/)?.[1],'_blank');}function renderIncidentList(list,items,empty){if(!list)return;list.innerHTML=items.length?items.map((item,index)=>incidentCard(item,index)).join(''):`<p class="documents-empty">${empty}</p>`;list.querySelectorAll('[data-incident-status]').forEach(button=>button.onclick=()=>updateIncidentStatus(button.dataset.incidentId,button.dataset.incidentStatus));list.querySelectorAll('[data-incident-email]').forEach(button=>button.onclick=()=>sendIncidentNow(button.dataset.incidentEmail));list.querySelectorAll('[data-incident-delete]').forEach(button=>button.onclick=()=>deleteRemoteIncident(button.dataset.incidentDelete));list.querySelectorAll('[data-incident-photos]').forEach(button=>button.onclick=()=>openIncidentPhotos(button.dataset.incidentPhotos));}
function renderIncidents(){const allItems=remoteIncidents.length?remoteIncidents:incidents;const terminal=['resolved','cancelled'];const active=allItems.filter(i=>!terminal.includes(String(i.status||'pending').toLowerCase()));const visible=currentRole==='admin'?(showIncidentHistory?allItems.filter(i=>terminal.includes(String(i.status||'').toLowerCase())):active):allItems.filter(i=>String(i.status||'pending').toLowerCase()==='reviewed');const incidentItems=visible.filter(i=>String(i.type||'Incidencia').toLowerCase()!=='sugerencia');const suggestionItems=visible.filter(i=>String(i.type||'').toLowerCase()==='sugerencia');renderIncidentList(incidentList,incidentItems,showIncidentHistory?'No hay incidencias cerradas en el histórico.':'Todavía no hay incidencias tramitadas.');renderIncidentList(suggestionList,suggestionItems,showIncidentHistory?'No hay sugerencias cerradas en el histórico.':'Todavía no hay sugerencias tramitadas.');const heading=document.querySelector('#incidentHeading'),note=document.querySelector('#incidentPermission'),toggle=document.querySelector('#incidentHistoryBtn');if(heading)heading.textContent=showIncidentHistory?'Histórico de incidencias y sugerencias':'Incidencias y sugerencias';if(note)note.textContent=currentRole==='admin'?(showIncidentHistory?'Actuaciones cerradas o eliminadas.':'Pendientes de tramitar o en seguimiento.'):'Aquí aparecen las comunicaciones que el administrador ya ha tramitado.';if(toggle)toggle.textContent=showIncidentHistory?'← Volver a incidencias':'Ver histórico';}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[char]));}
function renderDocuments(){
  const list=document.querySelector('#documentList'); if(!list) return;
  const docs=documentSource==='remote' ? remoteDocuments : storedDocuments;
  list.innerHTML=docs.length ? docs.map((doc,index)=>{
    const title=escapeHtml(doc.title||doc.name||'Documento');
    const category=escapeHtml(doc.category||doc.type||'Documento');
    const description=escapeHtml(doc.description||'');
    const manage=documentSource==='remote' && currentRole==='admin' && documentView==='manage';
    const actions=documentSource==='remote' ? `<button type="button" class="document-open" data-document-path="${escapeHtml(doc.storage_path)}" aria-label="Abrir ${title}">↗</button>${manage?`<button type="button" class="document-remove" data-remote-path="${escapeHtml(doc.storage_path)}" data-remote-id="${escapeHtml(doc.id)}" aria-label="Quitar ${title}">×</button>`:''}` : `<button type="button" class="document-remove" data-document-index="${index}" aria-label="Quitar ${title}">×</button>`;
    const descriptionView=manage ? `<div class="document-description-edit"><input type="text" value="${description}" placeholder="Aclara para qué sirve este documento" data-description-input="${escapeHtml(doc.id)}"><button type="button" class="document-save-description" data-description-id="${escapeHtml(doc.id)}">Guardar</button></div>` : (description?`<small class="document-description">${description}</small>`:'');
    return `<div class="document-row"><span class="document-icon">▤</span><div><strong>${title}</strong><small>${category} · Documento compartido</small>${descriptionView}</div>${actions}</div>`;
  }).join('') : '<p class="documents-empty">Todavía no hay documentos añadidos.</p>';
  list.querySelectorAll('[data-document-index]').forEach(button=>button.onclick=()=>{storedDocuments.splice(Number(button.dataset.documentIndex),1);localStorage.setItem('comunidad-documents',JSON.stringify(storedDocuments));renderDocuments();showToast('Documento quitado.');});
  list.querySelectorAll('[data-document-path]').forEach(button=>button.onclick=()=>openRemoteDocument(button.dataset.documentPath));
  list.querySelectorAll('[data-remote-path]').forEach(button=>button.onclick=()=>deleteRemoteDocument(button.dataset.remotePath,button.dataset.remoteId));
  list.querySelectorAll('[data-description-id]').forEach(button=>button.onclick=()=>saveDocumentDescription(button.dataset.descriptionId));
}
async function saveDocumentDescription(id){ const input=document.querySelector(`[data-description-input="${CSS.escape(id)}"]`); if(!input||!supabaseClient||!supabaseSession) return; const description=input.value.trim(); const {error}=await supabaseClient.from('documents').update({description}).eq('id',id); if(error){showToast(`No se pudo guardar la descripción: ${error.message}`);return;} const doc=remoteDocuments.find(item=>item.id===id); if(doc) doc.description=description; renderDocuments(); showToast('Descripción guardada.'); }
async function deleteRemoteDocument(path,id){ if(!supabaseClient || !supabaseSession || currentRole!=='admin') return; const name=remoteDocuments.find(doc=>doc.id===id)?.title||'este documento'; if(!window.confirm(`¿Quieres quitar «${name}» de la comunidad?`)) return; const {error:storageError}=await supabaseClient.storage.from('community-documents').remove([path]); if(storageError){showToast(`No se pudo quitar el archivo: ${storageError.message}`); return;} const {error:rowError}=await supabaseClient.from('documents').delete().eq('id',id); if(rowError){showToast(`No se pudo quitar el registro: ${rowError.message}`); return;} await refreshRemoteDocuments(); showToast('Documento quitado.'); }
async function refreshRemoteDocuments(){ if(!supabaseClient || !supabaseSession) return false; const {data,error}=await supabaseClient.from('documents').select('*').order('created_at',{ascending:false}); if(error){showToast(`No se pudieron consultar los documentos: ${error.message}`); return false;} remoteDocuments=data||[]; documentSource='remote'; renderDocuments(); return true; }
async function refreshRemoteNotices(){if(!supabaseClient||!supabaseSession)return false;const {data,error}=await supabaseClient.from('community_notices').select('*').order('event_date',{ascending:true}).order('created_at',{ascending:false});if(error){showToast(`No se pudieron consultar los avisos: ${error.message}`);return false;}notices.splice(0,notices.length,...(data||[]).map(item=>{const dateInfo=formatNoticeDate(item.event_date);return {...item,date:dateInfo.day,month:dateInfo.month,eventDate:item.event_date};}));renderNotices();renderCalendar();refreshNoveltyNotifications();return true;}
async function refreshRemoteIncidents(){if(!supabaseClient||!supabaseSession)return false;const {data,error}=await supabaseClient.from('community_incident_notifications').select('*').order('created_at',{ascending:false});if(error){showToast(`No se pudieron consultar las incidencias: ${error.message}`);return false;}remoteIncidents=data||[];renderIncidents();refreshNoveltyNotifications();return true;}
