function setIncidentButtonsBusy(id,busy){document.querySelectorAll('.incident-actions button').forEach(button=>{const buttonId=button.dataset.incidentId||button.dataset.incidentEmail||button.dataset.incidentDelete;if(String(buttonId)===String(id))button.disabled=busy;});}
function beginIncidentAction(id){if(incidentActionsInFlight.has(String(id))){showToast('Esta incidencia ya se está procesando. Espera un momento.');return false;}incidentActionsInFlight.add(String(id));setIncidentButtonsBusy(id,true);return true;}
function endIncidentAction(id){incidentActionsInFlight.delete(String(id));setIncidentButtonsBusy(id,false);}
async function sendIncidentNow(id){if(!supabaseClient||!supabaseSession||currentRole!=='admin')return;const item=remoteIncidents.find(i=>String(i.id)===String(id));if(!item||String(item.type||'Incidencia').toLowerCase()==='sugerencia'||item.sent_at||item.email_status==='sent')return;if(!beginIncidentAction(id))return;try{await sendIncidentEmail(item,{manual:true});await refreshRemoteIncidents();showToast('Correo enviado. La incidencia sigue pendiente de tramitar.');}catch(error){await refreshRemoteIncidents();showToast(`No se pudo enviar el correo. ${error.message||''}`);}finally{endIncidentAction(id);}}
async function updateIncidentStatus(id,status){if(!supabaseClient||!supabaseSession||currentRole!=='admin')return;const item=remoteIncidents.find(i=>String(i.id)===String(id));if(!item||!beginIncidentAction(id))return;try{const isIncident=String(item.type||'Incidencia').toLowerCase()!=='sugerencia';const shouldSend=status==='reviewed'&&isIncident&&String(item.status||'pending').toLowerCase()==='pending'&&!item.sent_at&&item.email_status!=='sent';if(shouldSend){try{await sendIncidentEmail(item,{manual:true});}catch(error){await refreshRemoteIncidents();showToast(`No se pudo tramitar ni enviar el correo. La incidencia sigue pendiente y puedes reintentarlo. ${error.message||''}`);return;}}const {data,error}=await supabaseClient.from('community_incident_notifications').update({status,updated_at:new Date().toISOString()}).eq('id',id).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('El servidor no autorizó el cambio o la incidencia ya no existe.');await refreshRemoteIncidents();showToast(shouldSend?'Incidencia tramitada y correo enviado.':`Incidencia marcada como ${incidentStatusLabels[status].toLowerCase()}.`);}catch(error){await refreshRemoteIncidents();showToast(`No se pudo actualizar la incidencia. ${error.message||''}`);}finally{endIncidentAction(id);}}
async function deleteRemoteIncident(id){if(!supabaseClient||!supabaseSession||currentRole!=='admin')return;if(!window.confirm('¿Quieres eliminar esta incidencia?'))return;if(!beginIncidentAction(id))return;try{const {data,error}=await supabaseClient.from('community_incident_notifications').update({status:'cancelled',updated_at:new Date().toISOString()}).eq('id',id).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('El servidor no autorizó el cambio o la incidencia ya no existe.');await refreshRemoteIncidents();showToast('Incidencia archivada en el historial.');}catch(error){await refreshRemoteIncidents();showToast(`No se pudo archivar la incidencia. ${error.message||''}`);}finally{endIncidentAction(id);}}
async function deleteRemoteNotice(id){if(!supabaseClient||!supabaseSession||currentRole!=='admin')return;const {error}=await supabaseClient.from('community_notices').delete().eq('id',id);if(error){showToast(`No se pudo eliminar el aviso: ${error.message}`);return;}await refreshRemoteNotices();showToast('Aviso eliminado.');}
async function refreshNeighborAccess(){
  if(!invitationCode||!supabaseClient||!supabaseSession)return;
  const wasApproved=neighborApproved;
  await checkNeighborAccess();
  if(neighborApproved){
    await refreshRemoteDocuments();
    await refreshRemoteNotices();
  }
  applyAccessGate();
  if(neighborApproved&&!wasApproved)showToast('Acceso autorizado. Ya puedes consultar la comunidad.');
}
function subscribeToRealtime(){if(!supabaseClient||!supabaseSession)return;if(realtimeChannel)supabaseClient.removeChannel(realtimeChannel);realtimeChannel=supabaseClient.channel('community-live').on('postgres_changes',{event:'*',schema:'public',table:'community_notices'},()=>refreshRemoteNotices()).on('postgres_changes',{event:'*',schema:'public',table:'documents'},()=>refreshRemoteDocuments()).on('postgres_changes',{event:'*',schema:'public',table:'community_incident_notifications'},()=>refreshRemoteIncidents()).on('postgres_changes',{event:'*',schema:'public',table:'community_access_requests'},()=>{if(currentRole==='admin'){refreshAccessRequests();refreshApprovedResidents();}else if(invitationCode)refreshNeighborAccess();}).subscribe();}
async function openRemoteDocument(path){ const {data,error}=await supabaseClient.storage.from('community-documents').createSignedUrl(path,600); if(error){showToast('No se pudo abrir el documento.'); return;} window.open(data.signedUrl,'_blank','noopener'); }
