document.querySelector('#recoverAdminPasswordBtn').onclick=async()=>{if(!supabaseClient){showToast('No se pudo conectar con el sistema de acceso.');return;}const username=String(document.querySelector('#authForm [name="username"]').value||'').trim().toLowerCase();let email=username.includes('@')?username:null;if(!email){const {data,error}=await supabaseClient.rpc('resolve_admin_username',{p_username:username||'administrador'});if(error||!data){showToast('Escribe el usuario administrador para localizar la cuenta.');return;}email=data;}const redirectTo=`${window.location.origin}${window.location.pathname}`;const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo});if(error){showToast(`No se pudo enviar el enlace: ${error.message||''}`);return;}showToast('Enlace enviado al correo del administrador. Revisa también Spam.');};
document.querySelector('#notificationsBtn').onclick=async()=>{const panel=document.querySelector('#notificationsPanel');if(!panel)return;panel.hidden=!panel.hidden;if(!panel.hidden){const latest=notices.map(item=>item.created_at||'').sort().pop();if(latest)localStorage.setItem('comunidad-last-notice-seen',latest);const currentIds=remoteIncidents.filter(item=>String(item.status||'pending').toLowerCase()==='pending'&&String(item.type||'Incidencia').toLowerCase()==='incidencia').map(item=>String(item.id));let seen=[];try{seen=JSON.parse(localStorage.getItem('comunidad-seen-incidents')||'[]');}catch{}localStorage.setItem('comunidad-seen-incidents',JSON.stringify([...new Set([...seen,...currentIds])]));const incomingRole=currentRole==='admin'?'neighbor':'admin';const {data:unreadChats}=await supabaseClient.from('community_chat_messages').select('id').eq('sender_role',incomingRole).is('read_at',null);const seenChatIds=unreadChats||[];localStorage.setItem('comunidad-seen-chats',JSON.stringify(seenChatIds.map(item=>String(item.id))));noveltyState={chat:0,incidents:0,notices:0};const badge=document.querySelector('#notificationBadge'),noticeBadge=document.querySelector('#noticeUnreadCount');if(badge){badge.textContent='0';badge.hidden=true;}if(noticeBadge){noticeBadge.textContent='0';noticeBadge.hidden=true;}renderNoveltyNotifications();}};
