async function uploadIncidentPhotos(incidentId,files){if(!files.length)return[];const uploaded=[];for(const file of files){if(!file.type.startsWith('image/'))throw new Error('Solo se pueden adjuntar imágenes.');const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`${supabaseSession.user.id}/${incidentId}/${crypto.randomUUID()}-${safeName}`;const {error}=await supabaseClient.storage.from('incident-photos').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(error)throw new Error(`No se pudo subir la foto «${file.name}»: ${error.message}`);uploaded.push({path,name:file.name,type:file.type,size:file.size});}const {error}=await supabaseClient.from('community_incident_notifications').update({attachments:uploaded}).eq('id',incidentId);if(error)throw new Error(`No se pudieron guardar las fotos: ${error.message}`);return uploaded;}
const incidentPhotoInput=document.querySelector('#incidentPhotoInput'),incidentPhotoList=document.querySelector('#incidentPhotoList'),incidentPhotoAdd=document.querySelector('#incidentPhotoAdd');function renderIncidentPhotoList(){if(!incidentPhotoList)return;incidentPhotoList.innerHTML=incidentPhotoFiles.length?incidentPhotoFiles.map(file=>`<span>${file.name}</span>`).join(''):'<span class="photo-empty">No has seleccionado fotos.</span>';}incidentPhotoInput?.addEventListener('change',()=>{const selected=Array.from(incidentPhotoInput.files||[]);for(const file of selected){if(!incidentPhotoFiles.some(existing=>existing.name===file.name&&existing.size===file.size&&existing.lastModified===file.lastModified))incidentPhotoFiles.push(file);}incidentPhotoInput.value='';renderIncidentPhotoList();});incidentPhotoAdd?.addEventListener('click',()=>incidentPhotoInput?.click());renderIncidentPhotoList();document.querySelector('#incidentForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,data=new FormData(form),type=String(data.get('type')||'Incidencia').trim(),title=String(data.get('title')||'').trim(),message=String(data.get('message')||'').trim(),location=String(data.get('location')||'').trim(),photos=incidentPhotoFiles.slice();if(!supabaseClient||!supabaseSession){showToast('Necesitas iniciar sesión para comunicar una incidencia.');return;}const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const {data:incidentId,error}=await supabaseClient.rpc('notify_new_incident',{p_title:title,p_message:message,p_location:location||null,p_type:type});if(error)throw new Error(error.message||'No se pudo guardar la comunicación.');if(photos.length)await uploadIncidentPhotos(incidentId,photos);closeModal('incidentModal');form.reset();incidentPhotoFiles=[];renderIncidentPhotoList();await refreshRemoteIncidents();if(type.toLowerCase()==='incidencia'){try{const result=await sendIncidentEmail({id:incidentId});if(result.sent)showToast('Incidencia enviada también por correo al administrador.');else if(result.skipped)showToast('Incidencia guardada y pendiente de revisión.');else showToast('Incidencia registrada.');}catch(error){await refreshRemoteIncidents();showToast(`Incidencia guardada, pero quedó pendiente de envío de correo: ${error.message||''}`);}}else showToast(currentRole==='admin'?'Comunicación registrada y pendiente de tramitar.':'Comunicación enviada al administrador y pendiente de revisión.');}catch(error){showToast(error.message||'No se pudo guardar la comunicación.');}finally{submit.disabled=false;}};
document.querySelectorAll('.role-choice').forEach(button=>button.onclick=()=>{ currentRole=button.dataset.role; document.querySelectorAll('.role-choice').forEach(item=>item.classList.toggle('active',item===button)); const admin=currentRole==='admin'; document.querySelector('#roleName').textContent=admin?'Administrador de la aplicación':'Vecino'; document.querySelector('#roleDescription').textContent=admin?'Gestionas la información que se publica para toda la comunidad.':'Puedes consultar la información y comunicar incidencias visibles para toda la comunidad.'; document.querySelector('#topRole').textContent=admin?'Administrador de la aplicación':'Vecino'; document.querySelector('.avatar').textContent=admin?'ES':'V'; document.querySelector('#newNoticeBtn').hidden=!admin; document.querySelector('#noticePermission').textContent=admin?'Solo el administrador de la aplicación puede publicar avisos visibles para toda la comunidad.':'Aquí puedes consultar los avisos publicados por el administrador de la aplicación.'; document.querySelector('#incidentHeading').textContent='Incidencias y sugerencias'; document.querySelector('#incidentPermission').textContent=admin?'Gestiona las incidencias que te comunican los vecinos.':'Las comunicaciones solo aparecen a los vecinos cuando el administrador las tramita.'; document.querySelector('#newIncidentBtn').textContent=admin?'＋ Registrar incidencia':'＋ Enviar al administrador'; document.querySelector('#incidentTitle').textContent=admin?'Registrar incidencia':'Enviar al administrador'; document.querySelector('#incidentIntro').textContent=admin?'Registra una incidencia para hacer seguimiento.':'La comunicación queda pendiente de revisión. Los vecinos la verán cuando el administrador la tramite.'; document.querySelector('#incidentSubmit').textContent=admin?'Guardar incidencia':'Enviar al administrador'; document.querySelector('#solicitudes').hidden=!admin; document.querySelector('#profileLabel').textContent=admin?'ADMINISTRADOR DE LA APLICACIÓN':'VECINO'; document.querySelector('#profileName').textContent=admin?'Eduardo Santamaría':'Nombre del vecino'; document.querySelector('#profileAddress').textContent=admin?'Portal 1 · 1.º F':'Portal y piso'; document.querySelector('#profileStatus').textContent=admin?'Cuenta administradora':'Cuenta pendiente de verificación';updateChatAccessButtons(); });
