function syncDocumentPermissions(){
  const admin=currentRole==='admin' && Boolean(supabaseSession) && !supabaseSession.user?.is_anonymous;
  document.querySelector('#manageDocumentsBtn').hidden=!admin;
  document.querySelector('#manageDocumentsTab').hidden=!admin;
  if(!admin && documentView==='manage') documentView='consult';
  setDocumentView(documentView);
  document.querySelector('#incidentHistoryBtn').hidden=!admin;const passwordButton=document.querySelector('#changeAdminPasswordBtn');if(passwordButton)passwordButton.hidden=!admin;const setting=document.querySelector('#incidentEmailSetting');if(setting)setting.hidden=!admin;updateChatAccessButtons(); if(admin&&supabaseSession&&!supabaseSession.user?.is_anonymous)loadIncidentEmailSetting();
}
